class Solution {
    public int findKthLargest(int[] nums, int k) {
        // Min-Heap keeps exactly k largest elements seen so far
        PriorityQueue<Integer> minHeap = new PriorityQueue<>();
        for (int num : nums) {
            minHeap.add(num);
            if (minHeap.size() > k) {
                minHeap.poll(); // Kick out the smallest guy
            }
        }
        return minHeap.peek(); // The k-th largest is sitting at the absolute top
    }
}

