class Solution {
    public boolean validPath(int n, int[][] edges, int start, int end) {
        Map<Integer, List<Integer>> adj = new HashMap<>();
        for (int[] edge : edges) {
            adj.computeIfAbsent(edge[0], k -> new ArrayList<>()).add(edge[1]);
            adj.computeIfAbsent(edge[1], k -> new ArrayList<>()).add(edge[0]);
        }
        Set<Integer> visited = new HashSet<>();
        return dfs(adj, start, end, visited);
    }
    private boolean dfs(Map<Integer, List<Integer>> adj, int curr, int target, Set<Integer> visited) {
        if (curr == target) return true;
        if (!visited.add(curr)) return false; // Found a cycle / already been here!
        for (int neighbor : adj.getOrDefault(curr, new ArrayList<>())) {
            if (dfs(adj, neighbor, target, visited)) return true;
        }
        return false;
    }
}

