class Solution {
    public boolean canJump(int[] nums) {
        // Start the goalpost at the absolute ending index
        int goal = nums.length - 1;

        // Work backwards greedily
        for (int i = nums.length - 2; i >= 0; i--) {
            if (i + nums[i] >= goal) {
                goal = i; // Move the goalpost closer!
            }
        }

        // If the goalpost successfully reached the start, we win.
        return goal == 0;
    }
}

